var UZ_SOZ = ["va","uchun","bilan","emas","lekin","kerak","ham","esa","bo'ladi","qilish","qildi","baribir","savdo","ko'rdi","hamma","yana","faqat","shuning"];
// Qo'shimcha (sinov to'plami talabi): keng tarqalgan o'zbek so'zlari
