function numToTr(n){
  n=Math.floor(Math.abs(n));
  if(n===0)return 'sıfır';
  var b=['','bir','iki','üç','dört','beş','altı','yedi','sekiz','dokuz'];
  var o=['','on','yirmi','otuz','kırk','elli','altmış','yetmiş','seksen','doksan'];
  var r='';
  if(n>=1000000000){r+=numToTr(Math.floor(n/1000000000))+' milyar ';n=n%1000000000;}
  if(n>=1000000){r+=numToTr(Math.floor(n/1000000))+' milyon ';n=n%1000000;}
  if(n>=1000){var t=Math.floor(n/1000);r+=(t===1?'':numToTr(t)+' ')+'bin ';n=n%1000;}
  if(n>=100){var h=Math.floor(n/100);r+=(h===1?'':b[h]+' ')+'yüz ';n=n%100;}
  if(n>=20){r+=o[Math.floor(n/10)];n=n%10;if(n>0){r+=' '+b[n];n=0;}}
  else if(n>=10){r+='on'+(n>10?' '+b[n-10]:'');n=0;}
  if(n>0)r+=(r.trim()?' ':'')+b[n];
  return r.trim();
}
function toTr(text){
