var qisqa = function (s, max) {
  s = String(s || ""); if (s.length <= max) return s;
  var ch = Array.from(s); var cut = ""; for (var i = 0; i < ch.length; i++) { if ((cut + ch[i]).length > max) break; cut += ch[i]; }
  var best = -1; for (var k = 0; k < cut.length; k++) { var c = cut.charAt(k); if ((c === "." || c === "!" || c === "?" || c === "…") && (k === cut.length - 1 || /\s/.test(cut.charAt(k + 1)))) best = k; }
  if (best >= 0) return cut.slice(0, best + 1).trim();
  var sp = cut.lastIndexOf(" "); return (sp > 0 ? cut.slice(0, sp) : cut).trim();
};
if (CAP_MAX > 0 && typeof j.tavsif === "string" && j.tavsif.length > CAP_MAX) { var c0 = j.tavsif.length; j.tavsif = qisqa(j.tavsif, CAP_MAX); tuz.push("tavsif " + c0 + " → " + j.tavsif.length + " belgi (max " + CAP_MAX + ")"); }
if (typeof j.tts_matn === "string" && /[«»]/.test(j.tts_matn)) { j.tts_matn = j.tts_matn.replace(/[«»]/g, ""); tuz.push("tts_matn: « » olib tashlandi"); }
