// QULF bloklar so'zma-so'z qoladi; qolgan bloklar minSoz gacha kengaytiriladi (pasport o'zgarmaydi)
var ds = $("YT · Bloklarni yig'ish").first().json;
var bl = (ds.bloklar || []).slice();
var wc = function (s) { return String(s || "").split(/\s+/).filter(Boolean).length; };
var matnOf = function (b) { return b.matn || b.matn_tr || ""; };
var qulfSoz = 0, ochiq = [], kontekst = [];
bl.forEach(function (b) { var w = wc(matnOf(b)); if (String(b.rejim || "").toUpperCase() === "QULF") { qulfSoz += w; kontekst.push("[" + b.blok + "] " + matnOf(b)); } else { ochiq.push({ b: b, w: w }); } });
var minSoz = parseInt(ds.minSoz || 0, 10) || 0;
var jami = qulfSoz + ochiq.reduce(function (a, x) { return a + x.w; }, 0);
var byudjet = Math.max(0, minSoz - qulfSoz);
var maqsad = Math.round(byudjet * 1.25);
var sekJami = ochiq.reduce(function (a, x) { return a + (parseFloat(x.b.sek) || 1); }, 0) || 1;
var reja = ochiq.map(function (x) { var ul = (parseFloat(x.b.sek) || 1) / sekJami; var mn = Math.max(x.w, Math.round(maqsad * ul)); return { id: x.b.id, blok: x.b.blok, rejim: x.b.rejim, sek: x.b.sek, asl_matn: matnOf(x.b), asl_soz: x.w, min_soz: mn, max_soz: Math.round(mn * 1.3) }; });
var faktlar_qisqa = (ds.faktlar || []).map(function (f) { return { s_id: f.s_id, matn: f.matn || f.matn_tr, manba: f.manba }; });
return [{ json: Object.assign({}, ds, { kengaytirish: ochiq.length > 0 && jami < minSoz, qulf_soz: qulfSoz, jami_soz: jami, byudjet: byudjet, reja: reja, faktlar_qisqa: faktlar_qisqa, qulf_kontekst: kontekst.join("\n") }) }];

// Kengaytirilgan bloklarni asl tartibda yig'adi; QULF bloklar so'zma-so'z
var rj = $("YT · Kengaytirish rejasi").first().json;
var raw = ($json.content && $json.content[0] && $json.content[0].text) || "";
var map = {}; var parseXato = false;
try { var s = raw.indexOf("{"), e = raw.lastIndexOf("}"); var p = JSON.parse(raw.slice(s, e + 1)); (p.bloklar || []).forEach(function (b) { map[String(b.id)] = String(b.matn || ""); }); } catch (err) { parseXato = true; }
var wc = function (t) { return String(t || "").split(/\s+/).filter(Boolean).length; };
var ishlatildi = 0;
var bloklar_yakuniy = (rj.bloklar || []).map(function (b) { var asl = b.matn || b.matn_tr || ""; var m = asl; if (String(b.rejim || "").toUpperCase() !== "QULF") { var k = map[String(b.id)]; if (k && wc(k) >= wc(asl)) { ishlatildi++; m = k; } } return { id: b.id, blok: b.blok, rejim: b.rejim, matn: m }; });
var tts = bloklar_yakuniy.map(function (b) { return b.matn; }).filter(Boolean).join("\n\n");
