// Bir martalik to'ldirish: eng katta 90% blok almashtiriladi (faqat uzunroq bo'lsa)
var km = $("YT · Kengaytirilgan matn").first().json;
var raw = ($json.content && $json.content[0] && $json.content[0].text) || "";
var wc = function (t) { return String(t || "").split(/\s+/).filter(Boolean).length; };
var yangi = null, id = null;
try { var s = raw.indexOf("{"), e = raw.lastIndexOf("}"); var p = JSON.parse(raw.slice(s, e + 1)); if (p.bloklar && p.bloklar[0]) { yangi = String(p.bloklar[0].matn || ""); id = String(p.bloklar[0].id); } } catch (err) {}
var bl = (km.bloklar_yakuniy || []).map(function (b) { if (yangi && String(b.id) === id && wc(yangi) > wc(b.matn)) return Object.assign({}, b, { matn: yangi }); return b; });
