return [{ json: Object.assign({}, km, { tts_final: tts, bloklar_yakuniy: bl, kengaytirilgan_soz: wc(tts), rejim_info: km.rejim_info + " + to'ldirish (" + (km.kengaytirilgan_soz || 0) + " → " + wc(tts) + ")" }) }];
